const peerScript=document.createElement('script');peerScript.src='https://unpkg.com/peerjs@1.5.4/dist/peerjs.min.js';document.head.append(peerScript);
function waitPeer(){return new Promise(function(resolve,reject){let n=0;const t=setInterval(function(){if(window.Peer){clearInterval(t);resolve()}else if(++n>80){clearInterval(t);reject()}},100)})}
const css=document.createElement('style');css.textContent='.online-entry{margin-top:8px;text-align:center}.online-entry button{font-size:10px;background:transparent;color:#d5bc91;border:1px solid #4b4c43;padding:7px 12px;border-radius:4px}.online-backdrop{position:fixed;inset:0;z-index:110;background:#050806e8;backdrop-filter:blur(8px);display:flex;align-items:center;justify-content:center}.online-backdrop.hidden{display:none}.online-panel{width:min(480px,94vw);background:#172019;border:1px solid #9e7c50;border-radius:10px;padding:24px;text-align:center}.online-panel h2{font:32px Georgia;margin:0 0 8px}.online-panel p{font-size:11px;color:#aab2a0}.online-panel input{width:100%;margin:8px 0;padding:11px;border:1px solid #4b4c43;background:#242824;border-radius:4px;color:#eee}.online-actions{display:grid;gap:8px;margin-top:12px}.online-status{font-size:11px;color:#dfb171;min-height:18px;margin-top:14px}.online-close{margin-top:14px}.lobby.hidden{display:none}.lobby h3{font-size:10px;letter-spacing:2px;color:#dfb171;margin:18px 0 10px}.lobby-code{font-weight:800;color:#f1ca8d;letter-spacing:2px;font-size:18px}.lobby-players{display:grid;grid-template-columns:1fr 1fr;gap:8px;margin:12px 0}.lobby-player{border:1px solid #3b4939;border-radius:6px;padding:10px;font-size:11px}.lobby-player.ready{border-color:#dfb171;background:#303326}.lobby-select{display:flex;gap:8px}.lobby-select button{flex:1;padding:8px;font-size:10px}.lobby-select button.selected{border-color:#dfb171;background:#3d3b28}.lobby-start{width:100%;margin-top:14px}.lobby-start:disabled{cursor:not-allowed}.lobby-note{font-size:10px;color:#9fa993;margin-top:10px}';document.head.append(css);
let peer=null,conn=null,lastSnapshot=0,lastInput=0;
const net=window.__eclipseNet=window.__eclipseNet||{role:null,remoteInput:{move:0,block:false},input:null};
function stateOf(game){return{fighters:game.fighters.map(f=>({...f})),timer:game.timer,phase:game.phase,phaseT:game.phaseT,round:game.round,wins:[...game.wins],roundWinner:game.roundWinner,winner:game.winner,mode:game.mode}}
function bindHost(c){conn=c;net.role='host';net.remoteInput={move:0,block:false};conn.on('data',function(m){if(m?.type==='input')net.remoteInput=m.input||{move:0,block:false};if(m?.type==='choice'){lobby.guestChar=m.char;renderLobby()}});net.onEvents=function(events){if(conn?.open)conn.send({type:'events',events})};net.onFrame=function(game){const now=performance.now();if(conn?.open&&now-lastSnapshot>45){lastSnapshot=now;conn.send({type:'snapshot',state:stateOf(game)})}}}
function bindGuest(c){conn=c;net.role='guest';conn.on('data',function(m){if(m?.type==='snapshot'&&net.applySnapshot)net.applySnapshot(m.state);if(m?.type==='events'&&net.applySnapshot)net.applySnapshot({events:m.events});if(m?.type==='lobby'){lobby.hostChar=m.hostChar;lobby.connected=true;renderLobby()}if(m?.type==='start')startOnline(m.hostChar,m.guestChar)});net.onFrame=function(){const now=performance.now();if(conn?.open&&now-lastInput>35){lastInput=now;conn.send({type:'input',input:net.input?.[1]||{move:0,block:false}})}}}
net.applySnapshot=function(state){const g=net.game;if(!g||!state)return;if(state.fighters)g.fighters=state.fighters;['timer','phase','phaseT','round','roundWinner','winner','mode'].forEach(k=>{if(k in state)g[k]=state[k]});if(state.wins)g.wins=state.wins;if(state.events)g.events=state.events};
const lobby={hostChar:0,guestChar:1,connected:false,isOpen:false};
function chooseChar(n){if(lobby.role==='host')lobby.hostChar=n;else lobby.guestChar=n;renderLobby();if(conn?.open)conn.send({type:'choice',char:n})}
function selectArenaChar(n){const b=document.querySelector('[data-character="'+n+'"]');if(b)b.click()}
function startOnline(hostChar,guestChar){lobby.isOpen=false;document.querySelector('#mode').value='local';selectArenaChar(lobby.role==='host'?hostChar:guestChar);document.querySelector('#start').click();const panel=document.querySelector('#onlineBackdrop');if(panel)panel.classList.add('hidden')}
function renderLobby(){const p=document.querySelector('#onlineBackdrop');if(!p)return;const host=p.querySelector('#hostPlayer'),guest=p.querySelector('#guestPlayer');host.classList.toggle('ready',lobby.role==='host'||lobby.hostChar!==null);guest.classList.toggle('ready',lobby.role==='guest'||lobby.guestChar!==null);p.querySelector('#hostChoice').textContent=lobby.hostChar===0?'DEMONE':'NINJA';p.querySelector('#guestChoice').textContent=lobby.guestChar===0?'DEMONE':'NINJA';p.querySelector('#startOnline').disabled=!(lobby.role==='host'&&lobby.connected);p.querySelector('#onlineStatus').textContent=lobby.connected?'Entrambi collegati. Scegliete il personaggio.':p.querySelector('#onlineStatus').textContent}
function showLobby(){lobby.isOpen=true;document.querySelector('#onlineSetup').classList.add('hidden');document.querySelector('#onlineLobby').classList.remove('hidden');renderLobby()}
function onlineUI(){
 const entry=document.createElement('div');entry.className='online-entry';entry.innerHTML='<button id="onlineButton">⚔ Gioca online</button>';document.querySelector('#start').insertAdjacentElement('afterend',entry);
 const back=document.createElement('div');back.id='onlineBackdrop';back.className='online-backdrop hidden';back.innerHTML='<div class="online-panel"><div id="onlineSetup"><h2>Gioca online</h2><p>Crea una stanza e invia il codice all’altro giocatore, oppure inserisci un codice ricevuto.</p><div class="online-actions"><button class="primary" id="createRoom">Crea stanza</button><input id="roomCode" placeholder="Codice stanza"><button id="joinRoom">Entra nella stanza</button></div></div><div id="onlineLobby" class="lobby hidden"><h2>Lobby online</h2><div class="lobby-code" id="lobbyCode"></div><h3>Giocatori</h3><div class="lobby-players"><div class="lobby-player" id="hostPlayer">Host<br><strong id="hostChoice">DEMONE</strong></div><div class="lobby-player" id="guestPlayer">Giocatore 2<br><strong id="guestChoice">NINJA</strong></div></div><div class="lobby-select"><button id="chooseDemon">Demone</button><button id="chooseNinja">Ninja</button></div><button class="primary lobby-start" id="startOnline">AVVIA PARTITA</button><div class="lobby-note">L’host avvia la partita quando entrambi sono pronti.</div></div><div class="online-status" id="onlineStatus"></div><button class="online-close" id="closeOnline">Chiudi</button></div>';document.body.append(back);
 const status=m=>back.querySelector('#onlineStatus').textContent=m;
 const close=()=>{back.classList.add('hidden');lobby.connected=false;net.role=null;if(conn){conn.close();conn=null}if(peer){peer.destroy();peer=null}};
 entry.querySelector('#onlineButton').onclick=()=>{back.classList.remove('hidden');status('')};back.querySelector('#closeOnline').onclick=close;
 back.querySelector('#chooseDemon').onclick=()=>chooseChar(0);back.querySelector('#chooseNinja').onclick=()=>chooseChar(1);
 back.querySelector('#startOnline').onclick=()=>{if(conn?.open){conn.send({type:'start',hostChar:lobby.hostChar,guestChar:lobby.guestChar});startOnline(lobby.hostChar,lobby.guestChar)}};
 back.querySelector('#createRoom').onclick=async()=>{status('Creo la stanza…');try{await waitPeer();lobby.role='host';lobby.connected=false;const id='eclipse-'+Math.random().toString(36).slice(2,8);peer=new window.Peer(id);back.querySelector('#lobbyCode').textContent='Codice: '+id;peer.on('open',()=>{status('Condividi il codice con l’altro giocatore');showLobby()});peer.on('connection',incoming=>{bindHost(incoming);incoming.on('open',()=>{lobby.connected=true;incoming.send({type:'lobby',hostChar:lobby.hostChar,guestChar:lobby.guestChar});renderLobby();status('Giocatore collegato')})});peer.on('error',e=>status('Errore: '+e.type))}catch(e){status('Impossibile collegarsi al server online')}};
 back.querySelector('#joinRoom').onclick=async()=>{const id=back.querySelector('#roomCode').value.trim();if(!id){status('Inserisci il codice stanza');return}status('Connessione…');try{await waitPeer();lobby.role='guest';peer=new window.Peer();peer.on('open',()=>{conn=peer.connect(id);bindGuest(conn);conn.on('open',()=>{lobby.connected=true;back.querySelector('#lobbyCode').textContent='Connesso alla stanza';showLobby();conn.send({type:'lobby',hostChar:lobby.hostChar,guestChar:lobby.guestChar})})});peer.on('error',()=>status('Errore: codice non valido o stanza chiusa'))}catch(e){status('Impossibile collegarsi al server online')}};
}
onlineUI();
